-- S15P21E201-1876 — 장소 주소의 일본어·중국어(간체·번체). 한국관광공사가 이미 번역해 둔 주소를 넣는다.
--
-- 🔴 왜: 장소 이름은 관광공사 번역으로 나오는데(V20260930130000) 주소는 한국어·영어뿐이라, 일본어 화면에서 이름만
--    일본어이고 주소는 영어·한국어였다. 외국인이 길을 찾고 택시에 보여 줄 때 읽는 글이다.
--
-- 출처: 이름 이관과 같은 관광공사 일문·중문 관광정보 서비스(2026-09-16 수집, 공공누리) 의 addr1·addr2. 행 수: ja 159 · zh-Hans 145 · zh-Hant 129.
--
-- 잇는 규칙은 이름 이관과 같다(한국어 이름 열쇠 완전 일치 + 약 500m 좌표 — contentid 는 국문과 번호가 달라 못 쓴다).
-- 🔴 하나를 더 본다 — **구(區)가 같아야 한다.** 관광공사 행의 시군구 코드(1~16, 가나다순)를 한국어 구 이름으로 바꿔
--    우리 장소의 한국어 주소에 그 구가 있을 때만 넣는다. 구 경계 근처에서 이름이 같은 다른 곳의 주소가 붙지 않게.
--
-- 원본을 고친 것(아래 씨앗 행을 만들 때 적용했다):
--    - 넣지 않은 것: 주소가 한국어 그대로인 행(언어마다 3곳), 주소 없는 행, 시군구 코드와 주소 글자가 어긋난 행.
--    - 시 이름을 언어마다 하나로: ja 釜山広域市(원본에 「プサン広域市」 「釜山広域地」 섞임) · 간체 釜山广域市(번체 섞임) · 번체 釜山廣域市.
--    - 일본어 구 이름은 한자로(원본에 「ヘウンデ区」와 「海雲台区」가 섞임). 도로명·동 이름은 원본 그대로.
--    - addr2(동 이름 등)는 한국어가 없고 addr1 에 이미 없을 때만 뒤에 붙인다.
--    이미 값이 있는 칸은 덮지 않는다.
-- 빈 시험 DB 에서는 place 가 없어 0행이다.
ALTER TABLE place ADD COLUMN IF NOT EXISTS address_ja VARCHAR(300);
ALTER TABLE place ADD COLUMN IF NOT EXISTS address_zh_hans VARCHAR(300);
ALTER TABLE place ADD COLUMN IF NOT EXISTS address_zh_hant VARCHAR(300);

DROP TABLE IF EXISTS place_local_address_match;
DROP TABLE IF EXISTS place_local_address_seed;
CREATE TEMPORARY TABLE place_local_address_seed (
    lang          VARCHAR(8)   NOT NULL,
    address_local VARCHAR(300) NOT NULL,
    name_key      VARCHAR(200) NOT NULL,
    short_key     VARCHAR(200) NOT NULL,
    gu_ko         VARCHAR(10)  NOT NULL,
    lat           DOUBLE PRECISION NOT NULL,
    lng           DOUBLE PRECISION NOT NULL,
    content_id    VARCHAR(20)  NOT NULL
);

;

CREATE TEMPORARY TABLE place_local_address_match AS
SELECT DISTINCT ON (p.place_id, s.lang) p.place_id, s.lang, s.address_local
FROM place p
CROSS JOIN LATERAL (
    SELECT regexp_replace(regexp_replace(lower(p.name_ko), '[(（][^)）]*[)）]', '', 'g'), '[^0-9a-z가-힣]', '', 'g') AS full_key
) k
JOIN place_local_address_seed s
  ON abs(p.lat - s.lat) < 0.0045
 AND abs(p.lng - s.lng) < 0.0055
 AND (k.full_key = s.name_key
      OR (char_length(s.short_key) >= 2 AND replace(k.full_key, '부산', '') = s.short_key))
 -- 구가 같아야 한다. 「서구」가 「강서구」에, 「남구」가 「남구로」에 걸리지 않게 앞뒤를 공백·끝으로 막는다.
 AND p.address ~ ('(^|\s)' || s.gu_ko || '(\s|$)')
ORDER BY p.place_id, s.lang, (k.full_key = s.name_key) DESC, abs(p.lat - s.lat) + abs(p.lng - s.lng);

UPDATE place p SET address_ja = m.address_local
FROM place_local_address_match m
WHERE m.place_id = p.place_id AND m.lang = 'ja' AND p.address_ja IS NULL;

UPDATE place p SET address_zh_hans = m.address_local
FROM place_local_address_match m
WHERE m.place_id = p.place_id AND m.lang = 'zh-Hans' AND p.address_zh_hans IS NULL;

UPDATE place p SET address_zh_hant = m.address_local
FROM place_local_address_match m
WHERE m.place_id = p.place_id AND m.lang = 'zh-Hant' AND p.address_zh_hant IS NULL;

DROP TABLE place_local_address_match;
DROP TABLE place_local_address_seed;
